import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../Config/Routes/route_name.dart';import '../../../../main.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_icons.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import 'package:convex_bottom_bar/convex_bottom_bar.dart';import 'package:flutter/material.dart';import '../manager/main_cubit.dart';class BuildBottomNavigationBar extends StatelessWidget {  const BuildBottomNavigationBar({    super.key,  });  @override  Widget build(BuildContext context) {    return ConvexAppBar(      elevation: 5,      color: AppColors.grayscale70,      activeColor: AppColors.primaryColor,      backgroundColor: AppColors.backgroundColor,      style: TabStyle.fixedCircle,      initialActiveIndex: context.watch<MainCubit>().state,      onTabNotify: (index) {        if (index == 2) {          kNavigationService.navigateTo(AppRoutes.authentication);          return false;        }        return true;      },      items: [        TabItem(          icon: AppIcons.homeOutline,          activeIcon: AppIcons.homeFill,          title: context.local.Home,        ),        TabItem(          icon: AppIcons.compassOutline,          activeIcon: AppIcons.compassFill,          title: context.local.Explore,        ),        TabItem(          icon: AppIcons.scan,          title: context.local.Scan,        ),        TabItem(          icon: AppIcons.heartsOutline,          activeIcon: AppIcons.heartFill,          title: context.local.Favourite,        ),        TabItem(          icon: AppIcons.profileOutline,          activeIcon: AppIcons.profileFill,          title: context.local.Profile,        ),      ],      onTap: (int i) {        if (i == 2) {          kNavigationService.navigateTo(AppRoutes.authentication);        } else {          context.read<MainCubit>().changeIndex(i);        }      },    );  }}